import heapq


def seatManager(n, ops):
    nxt = 1
    freed = []
    out = []
    for t, x in ops:
        if t == 0:
            if freed:
                out.append(heapq.heappop(freed))
            else:
                out.append(nxt)
                nxt += 1
        else:
            heapq.heappush(freed, x)
    return out
